define(['core_filters/events', 'core/ajax', 'core/notification'], function(FilterEvents, Ajax, Notification) {
    var initEach = function(type, setupFn) {
        document.querySelectorAll('[data-bunamrag-interactive="' + type + '"]').forEach(function(container) {
            if (container.dataset.bunamragInited) {
                return;
            }
            container.dataset.bunamragInited = '1';
            setupFn(container);
            FilterEvents.notifyFilterContentUpdated([container]);
        });
    };
    var showGlobalFeedback = function(container, score, dataSelector, targetSelector) {
        var dataEl = container.querySelector(dataSelector);
        var target = container.querySelector(targetSelector);
        if (!dataEl || !target) {
            return;
        }
        var ranges = [];
        try {
            ranges = JSON.parse(dataEl.textContent || '[]');
        } catch (e) {
            ranges = [];
        }
        var match = ranges.find(function(range) {
            return score >= range.from && score <= range.to;
        });
        if (match) {
            target.innerHTML = match.feedback;
            target.hidden = false;
        }
    };
    var recordAttempt = function(container, score) {
        if (container.dataset.bunamragTrack !== '1') {
            return;
        }
        Ajax.call([{
            methodname: 'mod_bunamrag_record_interactive_attempt',
            args: {
                cmid: parseInt(container.dataset.bunamragCmid, 10),
                contentid: parseInt(container.dataset.bunamragContentid, 10),
                score: score
            }
        }])[0].catch(Notification.exception);
    };
    var showBlankFeedback = function(container, blankIndex, isRight) {
        var item = container.querySelector('.bunamrag-blank-feedback-items li[data-index="' + blankIndex + '"]');
        if (!item) {
            return;
        }
        var correct = item.querySelector('.bunamrag-blank-feedback-correct');
        var incorrect = item.querySelector('.bunamrag-blank-feedback-incorrect');
        if (correct) {
            correct.hidden = !isRight;
        }
        if (incorrect) {
            incorrect.hidden = isRight;
        }
        item.classList.toggle('is-correct', isRight);
        item.classList.toggle('is-incorrect', !isRight);
        item.hidden = false;
        var list = container.querySelector('.bunamrag-blank-feedback-list');
        if (list) {
            list.hidden = false;
        }
    };
    return {
        initEach: initEach,
        showGlobalFeedback: showGlobalFeedback,
        recordAttempt: recordAttempt,
        showBlankFeedback: showBlankFeedback
    };
});
